1	/**
2	 * groq/compound does not support custom function calling, so Glint uses a
3	 * text protocol: the model emits tool calls as sentinel-delimited JSON blocks.
4	 * Sentinels are chosen to never collide with compound's internal <tool> tags
5	 * or with markdown code fences.
6	 */
7	
8	export const TOOL_OPEN = "<glint:tool>";
9	export const TOOL_CLOSE = "</glint:tool>";
10	
11	export interface ToolCall {
12	  tool: string;
13	  args: Record<string, unknown>;
14	  raw: string;
15	}
16	
17	// Canonical XML form plus the legacy sentinel form — models drift between them.
18	const XML_RE = /<glint:tool>\s*([\s\S]*?)\s*<\/glint:tool>/g;
19	const SENTINEL_RE = /^[ \t]*<<<glint:tool[ \t]*\r?\n([\s\S]*?)^[ \t]*>>>(?:glint)?[ \t]*$/gm;
20	
21	export function parseToolCalls(text: string): ToolCall[] {
22	  const calls: ToolCall[] = [];
23	  for (const re of [XML_RE, SENTINEL_RE]) {
24	    for (const match of text.matchAll(re)) {
25	      const parsed = parseJsonLenient(match[1].trim());
26	      if (parsed && typeof parsed.tool === "string") {
27	        calls.push({
28	          tool: parsed.tool,
29	          args: (parsed.args as Record<string, unknown>) ?? {},
30	          raw: match[0],
31	        });
32	      }
33	    }
34	  }
35	  return calls;
36	}
37	
38	export function stripToolBlocks(text: string): string {
39	  return text
40	    .replace(XML_RE, "")
41	    .replace(SENTINEL_RE, "")
42	    .replace(/```\s*\n?\s*```/g, "")
43	    .replace(/\n{3,}/g, "\n\n")
44	    .trim();
45	}
46	
47	const OPENERS = ["<glint:tool>", "<<<glint:tool"];
48	
49	/** Cut streamed text at the first tool opener so blocks never flash on screen. */
50	export function visiblePrefix(streamed: string): string {
51	  let cut = streamed.length;
52	  for (const opener of OPENERS) {
53	    const idx = streamed.indexOf(opener);
54	    if (idx !== -1 && idx < cut) cut = idx;
55	  }
56	  if (cut < streamed.length) return streamed.slice(0, cut);
57	  // Hold back a partial opener at the tail (e.g. "<glint:to" mid-stream).
58	  for (const opener of OPENERS) {
59	    for (let k = Math.min(opener.length - 1, streamed.length); k > 0; k--) {
60	      if (streamed.endsWith(opener.slice(0, k))) return streamed.slice(0, -k);
61	    }
62	  }
63	  return streamed;
64	}
65	
66	function parseJsonLenient(body: string): { tool?: string; args?: unknown } | null {
67	  const cleaned = body
68	    .replace(/^```(?:json)?\s*/m, "")
69	    .replace(/```\s*$/m, "")
70	    .trim();
71	  try {
72	    return JSON.parse(cleaned);
73	  } catch {
74	    const start = cleaned.indexOf("{");
75	    if (start === -1) return null;
76	    let depth = 0;
77	    let inStr = false;
78	    let esc = false;
79	    for (let i = start; i < cleaned.length; i++) {
80	      const ch = cleaned[i];
81	      if (esc) {
82	        esc = false;
83	        continue;
84	      }
85	      if (ch === "\\") {
86	        esc = true;
87	        continue;
88	      }
89	      if (ch === '"') inStr = !inStr;
90	      if (inStr) continue;
91	      if (ch === "{") depth++;
92	      if (ch === "}") {
93	        depth--;
94	        if (depth === 0) {
95	          try {
96	            return JSON.parse(cleaned.slice(start, i + 1));
97	          } catch {
98	            return null;
99	          }
100	        }
101	      }
102	    }
103	    return null;
104	  }
105	}
106	
107	export function formatToolResults(
108	  results: Array<{ tool: string; status: "ok" | "error"; output: string }>,
109	): string {
110	  const parts = results.map(
111	    (r, i) =>
112	      `<glint:result n="${i + 1}" tool="${r.tool}" status="${r.status}">\n${r.output}\n</glint:result>`,
113	  );
114	  const failures = results.filter((r) => r.status === "error").length;
115	  const warning =
116	    failures > 0
117	      ? `\n\n⚠ ${failures} tool call(s) FAILED. Read the error, fix the cause, retry. Do NOT claim success while any required action failed.`
118	      : "";
119	  return `[tool results]\n${parts.join("\n")}${warning}`;
120	}
