42	const ACTION_CLAIM_RE =
43	  /\b(?:I (?:created|wrote|ran|executed|made|added|updated|edited|installed|saved|built|recorded)|(?:has|have) been (?:created|written|executed|run|made|updated|edited|saved|built|recorded|noted|remembered)|was (?:created|written|executed|run|made|updated|edited|saved|built|recorded)|successfully (?:created|wrote|written|ran|executed|updated|built|saved)|script has|file now contains|the output (?:is|was)|tests?\s+(?:now\s+)?(?:all\s+)?pass|all tests pass)/i;
44	
45	function claimsAction(text: string): boolean {
46	  return ACTION_CLAIM_RE.test(text);
47	}
48	
49	const SUCCESS_CLAIM_RE =
50	  /\b(?:all tests pass|tests?\s+(?:now\s+)?(?:all\s+)?pass(?:es|ed)?|task is (?:now )?(?:complete|done)|successfully|works as (?:expected|intended|requested)|is (?:now )?(?:complete|fixed|working|resolved))\b/i;
51	
52	function claimsSuccess(text: string): boolean {
53	  return SUCCESS_CLAIM_RE.test(text);
54	}
55	
56	const GUESSED_CONTENT_RE =
57	  /\b(?:illustrative|typical contents?|likely (?:contains?|stored|located|holds?|lives|includes?)|presumably|probably (?:contains?|holds?|has|includes?)|based on (?:naming|common) (?:conventions?|patterns?)|might look (?:like|similar)|would typically|\(presumed?\b|common patterns\))/i;
58	
59	function looksGuessed(text: string): boolean {
60	  return GUESSED_CONTENT_RE.test(text);
61	}
