144	/** Review whether the goal was achieved. Returns { done, reason }. */
145	export async function reviewGoal(
146	  state: AgentState,
147	  goal: string,
148	): Promise<{ done: boolean; reason: string }> {
149	  const transcript = state.messages
150	    .filter((m) => m.role !== "system")
151	    .map((m) => `[${m.role}]\n${m.content.slice(0, 3000)}`)
152	    .join("\n\n")
153	    .slice(-30_000);
154	
155	  const res = await chat(
156	    [
157	      {
158	        role: "system",
159	        content: `You are a goal reviewer. Your job: read the conversation transcript and decide whether the original goal was achieved.
160	
161	Key principle: match your judgment to the goal's nature. A conversational question ("how can you help?", "what is X?") is met by a relevant, substantive answer — tools are not required. A task goal ("fix the bug", "create a file") requires actual tool results.
162	
163	Rules:
164	- If the goal was conversational (a question, greeting, or request for info) and the agent gave a relevant, helpful response, answer YES.
165	- If the goal required concrete action (file edits, commands, code changes) and every part was accomplished with real tool results, answer YES.
166	- If the goal required action but any part was skipped, failed, or only described but not executed, answer NO.
167	- If the agent hit an iteration limit or got stuck on a task goal, answer NO.
168	
169	Respond with exactly one line: YES: <brief reason> or NO: <brief reason>.`,
170	      },
171	      {
172	        role: "user",
173	        content: `Goal: ${goal}\n\nTranscript:\n${transcript || "(empty)"}`,
174	      },
175	    ],
176	    { model: effectiveModels().subagent, maxTokens: 512 },
177	  );
178	
179	  const text = res.content.trim();
180	  if (/^\s*YES[:\s]/i.test(text) || /^\s*YES$/i.test(text)) {
181	    return { done: true, reason: text.replace(/^\s*YES:?\s*/i, "") };
182	  }
183	  return { done: false, reason: text.replace(/^\s*NO:?\s*/i, "") || "goal not fully achieved" };
184	}
