53	export function isSafeBash(command: string): boolean {
54	  const trimmed = command.trim();
55	  if (/[;&|><`$]/.test(trimmed.replace(/\$\{?\w+\}?/g, ""))) {
56	    if (!/^[\w\s./*'"=-]+\|\s*(head|tail|wc|sort|uniq|grep)\b[\w\s./*'"-]*$/.test(trimmed)) {
57	      return false;
58	    }
59	  }
60	  return SAFE_BASH_PREFIXES.some((p) => trimmed === p.trim() || trimmed.startsWith(p));
61	}
