401	export async function executeTool(
402	  tools: Map<string, ToolSpec>,
403	  name: string,
404	  args: Record<string, unknown>,
405	): Promise<{ status: "ok" | "error"; output: string }> {
406	  const started = Date.now();
407	  const tool = tools.get(name);
408	  if (!tool) {
409	    const known = [...tools.keys()].join(", ");
410	    return { status: "error", output: `unknown tool "${name}". Available: ${known}` };
411	  }
412	  try {
413	    const output = await tool.run(args);
414	    logger.info("tool.run", { tool: name, ms: Date.now() - started });
415	    trace("tool.run", { tool: name, args: summarizeArgs(args), ms: Date.now() - started, ok: true });
416	    return { status: "ok", output };
417	  } catch (err) {
418	    const message = err instanceof Error ? err.message : String(err);
419	    logger.warn("tool.error", { tool: name, error: message });
420	    trace("tool.run", { tool: name, args: summarizeArgs(args), ms: Date.now() - started, ok: false, error: message });
421	    return { status: "error", output: message };
422	  }
423	}
