425	function summarizeArgs(args: Record<string, unknown>): Record<string, unknown> {
426	  const out: Record<string, unknown> = {};
427	  for (const [k, v] of Object.entries(args)) {
428	    out[k] = typeof v === "string" && v.length > 200 ? v.slice(0, 200) + "…" : v;
429	  }
430	  return out;
431	}
