1	import { API_URL, GROQ_API_KEY } from "./config.ts";
2	import { trace } from "./diagnostics.ts";
3	import { logger } from "./logger.ts";
4	
5	export interface ChatMessage {
6	  role: "system" | "user" | "assistant";
7	  content: string;
8	}
9	
10	export interface Usage {
11	  prompt_tokens: number;
12	  completion_tokens: number;
13	  total_tokens: number;
14	}
15	
16	export interface BreakdownEntry {
17	  model: string;
18	  usage: Usage;
19	}
20	
21	export interface ChatResult {
22	  content: string;
23	  reasoning?: string;
24	  usage: Usage;
25	  breakdown?: BreakdownEntry[];
26	  model: string;
27	}
28	
29	export type DeltaChannel = "content" | "reasoning";
30	
31	export const DEFAULT_MAX_TOKENS = 8192;
32	
33	export interface ChatOptions {
34	  model: string;
35	  temperature?: number;
36	  maxTokens?: number;
37	  signal?: AbortSignal;
38	  onDelta?: (text: string, channel: DeltaChannel) => void;
39	  enabledTools?: string[];
40	}
41	
42	const MAX_RETRIES = 4;
43	
44	export async function chat(messages: ChatMessage[], opts: ChatOptions): Promise<ChatResult> {
45	  const body: Record<string, unknown> = {
46	    model: opts.model,
47	    messages,
48	    stream: true,
49	    temperature: opts.temperature ?? 0.2,
50	    max_tokens: opts.maxTokens ?? DEFAULT_MAX_TOKENS,
51	  };
52	  if (opts.enabledTools) {
53	    body.compound_custom = { tools: { enabled_tools: opts.enabledTools } };
54	  }
55	
56	  let lastError: unknown;
57	  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
58	    if (attempt > 0) {
59	      const wait = Math.min(2 ** attempt * 1000, 15000);
60	      logger.warn("groq.retry", { attempt, wait });
61	      await new Promise((r) => setTimeout(r, wait));
62	    }
63	    try {
64	      const started = Date.now();
65	      const res = await fetch(API_URL, {
66	        method: "POST",
67	        headers: {
68	          Authorization: `Bearer ${GROQ_API_KEY}`,
69	          "Content-Type": "application/json",
70	        },
71	        body: JSON.stringify(body),
72	        signal: opts.signal,
73	      });
74	      if (res.status === 429 || res.status >= 500) {
75	        lastError = new Error(`HTTP ${res.status}: ${(await res.text()).slice(0, 300)}`);
76	        continue;
77	      }
78	      if (!res.ok) {
79	        const detail = (await res.text()).slice(0, 500);
80	        throw new Error(`Groq API error ${res.status}: ${detail}`);
81	      }
82	      const result = await readStream(res, opts.onDelta);
83	      const elapsed = Date.now() - started;
84	      logger.info("groq.chat", { model: opts.model, ms: elapsed, usage: result.usage });
85	      trace("api.response", {
86	        model: opts.model,
87	        ms: elapsed,
88	        usage: result.usage,
89	        content_chars: result.content.length,
90	      });
91	      return result;
92	    } catch (err) {
93	      if (opts.signal?.aborted) throw new Error("aborted");
94	      lastError = err;
95	      const msg = String(err);
96	      if (msg.includes("Groq API error 4")) throw err;
97	    }
98	  }
99	  trace("api.error", { model: opts.model, error: String(lastError) });
100	  throw new Error(`Groq request failed after ${MAX_RETRIES + 1} attempts: ${lastError}`);
101	}
102	
103	async function readStream(
104	  res: Response,
105	  onDelta?: (t: string, channel: DeltaChannel) => void,
106	): Promise<ChatResult> {
107	  const reader = res.body!.getReader();
108	  const decoder = new TextDecoder();
109	  let buffer = "";
110	  let content = "";
111	  let reasoning = "";
112	  let usage: Usage = { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
113	  let breakdown: BreakdownEntry[] | undefined;
114	  let model = "";
115	
116	  while (true) {
117	    const { done, value } = await reader.read();
118	    if (done) break;
119	    buffer += decoder.decode(value, { stream: true });
120	    const lines = buffer.split("\n");
121	    buffer = lines.pop() ?? "";
122	    for (const line of lines) {
123	      const data = line.startsWith("data: ") ? line.slice(6).trim() : "";
124	      if (!data || data === "[DONE]") continue;
125	      try {
126	        const chunk = JSON.parse(data);
127	        model = chunk.model ?? model;
128	        const delta = chunk.choices?.[0]?.delta;
129	        if (delta?.content) {
130	          content += delta.content;
131	          onDelta?.(delta.content, "content");
132	        }
133	        if (delta?.reasoning) {
134	          reasoning += delta.reasoning;
135	          onDelta?.(delta.reasoning, "reasoning");
136	        }
137	        if (chunk.usage) usage = chunk.usage;
