const XML_RE = /<glint:tool>\s*([\s\S]*?)\s*<\/glint:tool>/g;

function parseJsonLenient(body: string): { tool?: string; args?: unknown } | null {
  const cleaned = body
    .replace(/^```(?:json)?\s*/m, "")
    .replace(/```\s*$/m, "")
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    const start = cleaned.indexOf("{");
    if (start === -1) return null;
    let depth = 0, inStr = false, esc = false;
    for (let i = start; i < cleaned.length; i++) {
      const ch = cleaned[i];
      if (esc) { esc = false; continue; }
      if (ch === "\\") { esc = true; continue; }
      if (ch === '"') inStr = !inStr;
      if (inStr) continue;
      if (ch === "{") depth++;
      if (ch === "}") { depth--; if (depth === 0) { try { return JSON.parse(cleaned.slice(start, i + 1)); } catch { return null; } } }
    }
    return null;
  }
}
function parse(text: string) {
  const calls: any[] = [];
  for (const match of text.matchAll(XML_RE)) {
    const parsed = parseJsonLenient(match[1].trim());
    if (parsed && typeof parsed.tool === "string") calls.push(parsed);
  }
  return calls;
}

